E=[('Redline 6 · the two counterfeits', 89, 'Now meet the two counterfeits, because Jesus puts both of them in the same story, and our whole culture is built out of them.', 'Now meet the two counterfeits of love, because our whole culture is built out of them. Jesus shows us one of them in the story itself; the other is the father this father refused to be.'), ('Redline 6 · the two counterfeits', 95, 'The culture offers us only these two sons.', 'The culture offers us only these two counterfeits.'), ('Redline 6 · the two counterfeits', 98, 'in a world that knows only the two sons.', 'in a world that knows only the two counterfeits.'), ('Redline 6 · the two counterfeits', 103, 'Most families know these two sons from the inside.', 'Most families know these two counterfeits from the inside.'), ('Redline 6 · the two counterfeits', 162, 'the two counterfeit sons are waiting', 'the two counterfeits are waiting'), ('Redline 6 · the two counterfeits', 166, 'the difference between the father and the two sons.', 'the difference between the father and the two counterfeits.'), ('Redline 6 · the two counterfeits', 258, 'you will choose one of the counterfeit sons after all.', 'you will choose one of the counterfeits after all.'), ('Redline 6 · the two counterfeits', 282, 'was I the father — or one of the two sons?*', 'was I the father — or one of the two counterfeits?*')]
